/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class PaymentsStoreResolver(
    private val store: PaymentsStore,
    model: Model,
) : StateResolver {
    private val questions = PaymentsStoreQuestions(model)

    override fun begin(kind: WorkKind): UnitOfWork = store.begin(kind)

    override fun fetchByKeys(shape: String, keys: List<StoreKey>): List<Row> = when (shape) {
        "Contact" -> store.contacts(keys).map { it.toRow() }
        "Card" -> store.cards(keys).map { it.toRow() }
        "Customer" -> store.customers(keys).map { it.toRow() }
        "CardUpdate" -> store.cardUpdates(keys).map { it.toRow() }
        "Order" -> store.orders(keys).map { it.toRow() }
        "ChargeAttempt" -> store.chargeAttempts(keys).map { it.toRow() }
        "ChargeResponse" -> store.chargeResponses(keys).map { it.toRow() }
        "AttemptTimeout" -> store.attemptTimeouts(keys).map { it.toRow() }
        "StockReservation" -> store.stockReservations(keys).map { it.toRow() }
        "ReservationRelease" -> store.reservationReleases(keys).map { it.toRow() }
        "Receipt" -> store.receipts(keys).map { it.toRow() }
        "Shipment" -> store.shipments(keys).map { it.toRow() }
        "ChangeShippingAddress" -> store.changeShippingAddresss(keys).map { it.toRow() }
        "AddressChangeApplication" -> store.addressChangeApplications(keys).map { it.toRow() }
        "AddressChangeRefusal" -> store.addressChangeRefusals(keys).map { it.toRow() }
        "Refund" -> store.refunds(keys).map { it.toRow() }
        "SettlementReversal" -> store.settlementReversals(keys).map { it.toRow() }
        "ManualCharge" -> store.manualCharges(keys).map { it.toRow() }
        "ExtensionRequest" -> store.extensionRequests(keys).map { it.toRow() }
        "PaymentExtension" -> store.paymentExtensions(keys).map { it.toRow() }
        "PaymentReminder" -> store.paymentReminders(keys).map { it.toRow() }
        "DunningFlag" -> store.dunningFlags(keys).map { it.toRow() }
        "DunningResolution" -> store.dunningResolutions(keys).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Contact" -> store.allContacts().map { it.toRow() }
        "Card" -> store.allCards().map { it.toRow() }
        "Customer" -> store.allCustomers().map { it.toRow() }
        "CardUpdate" -> store.allCardUpdates().map { it.toRow() }
        "Order" -> store.allOrders().map { it.toRow() }
        "ChargeAttempt" -> store.allChargeAttempts().map { it.toRow() }
        "ChargeResponse" -> store.allChargeResponses().map { it.toRow() }
        "AttemptTimeout" -> store.allAttemptTimeouts().map { it.toRow() }
        "StockReservation" -> store.allStockReservations().map { it.toRow() }
        "ReservationRelease" -> store.allReservationReleases().map { it.toRow() }
        "Receipt" -> store.allReceipts().map { it.toRow() }
        "Shipment" -> store.allShipments().map { it.toRow() }
        "ChangeShippingAddress" -> store.allChangeShippingAddresss().map { it.toRow() }
        "AddressChangeApplication" -> store.allAddressChangeApplications().map { it.toRow() }
        "AddressChangeRefusal" -> store.allAddressChangeRefusals().map { it.toRow() }
        "Refund" -> store.allRefunds().map { it.toRow() }
        "SettlementReversal" -> store.allSettlementReversals().map { it.toRow() }
        "ManualCharge" -> store.allManualCharges().map { it.toRow() }
        "ExtensionRequest" -> store.allExtensionRequests().map { it.toRow() }
        "PaymentExtension" -> store.allPaymentExtensions().map { it.toRow() }
        "PaymentReminder" -> store.allPaymentReminders().map { it.toRow() }
        "DunningFlag" -> store.allDunningFlags().map { it.toRow() }
        "DunningResolution" -> store.allDunningResolutions().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencingAny(shape: String, field: String, targets: List<Ref.Persisted>): List<Row> = when {
        shape == "Card" && field == "billingContact" -> store.cardsByBillingContacts(targets).map { it.toRow() }
        shape == "Customer" && field == "card" -> store.customersByCards(targets).map { it.toRow() }
        shape == "CardUpdate" && field == "customer" -> store.cardUpdatesByCustomers(targets).map { it.toRow() }
        shape == "CardUpdate" && field == "card" -> store.cardUpdatesByCards(targets).map { it.toRow() }
        shape == "Order" && field == "customer" -> store.ordersByCustomers(targets).map { it.toRow() }
        shape == "ChargeAttempt" && field == "order" -> store.chargeAttemptsByOrders(targets).map { it.toRow() }
        shape == "ChargeResponse" && field == "attempt" -> store.chargeResponsesByAttempts(targets).map { it.toRow() }
        shape == "AttemptTimeout" && field == "attempt" -> store.attemptTimeoutsByAttempts(targets).map { it.toRow() }
        shape == "StockReservation" && field == "order" -> store.stockReservationsByOrders(targets).map { it.toRow() }
        shape == "ReservationRelease" && field == "reservation" -> store.reservationReleasesByReservations(targets).map { it.toRow() }
        shape == "Receipt" && field == "attempt" -> store.receiptsByAttempts(targets).map { it.toRow() }
        shape == "Shipment" && field == "order" -> store.shipmentsByOrders(targets).map { it.toRow() }
        shape == "ChangeShippingAddress" && field == "order" -> store.changeShippingAddresssByOrders(targets).map { it.toRow() }
        shape == "AddressChangeApplication" && field == "change" -> store.addressChangeApplicationsByChanges(targets).map { it.toRow() }
        shape == "AddressChangeRefusal" && field == "change" -> store.addressChangeRefusalsByChanges(targets).map { it.toRow() }
        shape == "Refund" && field == "order" -> store.refundsByOrders(targets).map { it.toRow() }
        shape == "SettlementReversal" && field == "order" -> store.settlementReversalsByOrders(targets).map { it.toRow() }
        shape == "ManualCharge" && field == "order" -> store.manualChargesByOrders(targets).map { it.toRow() }
        shape == "ExtensionRequest" && field == "order" -> store.extensionRequestsByOrders(targets).map { it.toRow() }
        shape == "PaymentExtension" && field == "order" -> store.paymentExtensionsByOrders(targets).map { it.toRow() }
        shape == "PaymentReminder" && field == "order" -> store.paymentRemindersByOrders(targets).map { it.toRow() }
        shape == "DunningFlag" && field == "order" -> store.dunningFlagsByOrders(targets).map { it.toRow() }
        shape == "DunningResolution" && field == "flag" -> store.dunningResolutionsByFlags(targets).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Order")
            questions.neverChargedCandidates.match(filter)?.let { h -> return store.neverChargedCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.refundedOrderCandidates.match(filter)?.let { h -> return store.refundedOrderCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.chargeableOrderCandidates.match(filter)?.let { h -> return store.chargeableOrderCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.completedAttemptCandidates.match(filter)?.let { h -> return store.completedAttemptCandidates().map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.timedOutAttemptCandidates.match(filter)?.let { h -> return store.timedOutAttemptCandidates().map { it.toRow() } }
        if (shape == "StockReservation")
            questions.activeReservationCandidates.match(filter)?.let { h -> return store.activeReservationCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.retryableOrderCandidates.match(filter)?.let { h -> return store.retryableOrderCandidates().map { it.toRow() } }
        if (shape == "ChargeAttempt")
            questions.stalePendingAttemptCandidates.match(filter)?.let { h -> return store.stalePendingAttemptCandidates(h.instant(0)).map { it.toRow() } }
        if (shape == "Order")
            questions.unshippedOrderCandidates.match(filter)?.let { h -> return store.unshippedOrderCandidates().map { it.toRow() } }
        if (shape == "ChangeShippingAddress")
            questions.refusedAddressChangeCandidates.match(filter)?.let { h -> return store.refusedAddressChangeCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.overdueOrderCandidates.match(filter)?.let { h -> return store.overdueOrderCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "DunningFlag")
            questions.openDunningFlagCandidates.match(filter)?.let { h -> return store.openDunningFlagCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.reserveStockCandidates.match(filter)?.let { h -> return store.reserveStockCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.requestInitialChargeCandidates.match(filter)?.let { h -> return store.requestInitialChargeCandidates(h.date(0)).map { it.toRow() } }
        if (shape == "Order")
            questions.releaseStockOnExhaustionCandidates.match(filter)?.let { h -> return store.releaseStockOnExhaustionCandidates().map { it.toRow() } }
        if (shape == "Order")
            questions.remindPaymentCandidates.match(filter)?.let { h -> return store.remindPaymentCandidates(h.date(0), h.date(1)).map { it.toRow() } }
        if (shape == "Order")
            questions.openDunningEpisodeCandidates.match(filter)?.let { h -> return store.openDunningEpisodeCandidates(h.date(0)).map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
    }
}

private fun List<QConst>.date(i: Int): LocalDate = (this[i] as QConst.QDate).v
private fun List<QConst>.instant(i: Int): Instant = (this[i] as QConst.QDateTime).v

// ── row mappers: the generic wire format <-> the typed rows ──

fun Row.toContactRow(): ContactRow = ContactRow(
    key = key,
    name = fields["name"] as String,
    email = fields["email"] as String,
)

fun ContactRow.toRow(): Row = Row("Contact", key, buildMap {
    put("name", name)
    put("email", email)
})

fun Row.toCardRow(): CardRow = CardRow(
    key = key,
    number = fields["number"] as String,
    expiresOn = fields["expiresOn"] as LocalDate,
    billingContact = fields["billingContact"] as Ref.Persisted?,
)

fun CardRow.toRow(): Row = Row("Card", key, buildMap {
    put("number", number)
    put("expiresOn", expiresOn)
    billingContact?.let { put("billingContact", it) }
})

fun Row.toCustomerRow(): CustomerRow = CustomerRow(
    key = key,
    name = fields["name"] as String,
    card = fields["card"] as Ref.Persisted?,
)

fun CustomerRow.toRow(): Row = Row("Customer", key, buildMap {
    put("name", name)
    card?.let { put("card", it) }
})

fun Row.toCardUpdateRow(): CardUpdateRow = CardUpdateRow(
    key = key,
    customer = fields["customer"] as Ref.Persisted,
    card = fields["card"] as Ref.Persisted,
)

fun CardUpdateRow.toRow(): Row = Row("CardUpdate", key, buildMap {
    put("customer", customer)
    put("card", card)
})

fun Row.toOrderRow(): OrderRow = OrderRow(
    key = key,
    customer = fields["customer"] as Ref.Persisted,
    amount = fields["amount"] as BigDecimal,
    dueBy = fields["dueBy"] as LocalDate,
    shippingAddress = fields["shippingAddress"] as String,
    placedOn = fields["placedOn"] as Instant,
)

fun OrderRow.toRow(): Row = Row("Order", key, buildMap {
    put("customer", customer)
    put("amount", amount)
    put("dueBy", dueBy)
    put("shippingAddress", shippingAddress)
    put("placedOn", placedOn)
})

fun Row.toChargeAttemptRow(): ChargeAttemptRow = ChargeAttemptRow(
    key = key,
    order = fields["order"] as Ref.Persisted,
    amount = fields["amount"] as BigDecimal,
    attemptKey = fields["attemptKey"] as String,
    requestedOn = fields["requestedOn"] as Instant,
)

fun ChargeAttemptRow.toRow(): Row = Row("ChargeAttempt", key, buildMap {
    put("order", order)
    put("amount", amount)
    put("attemptKey", attemptKey)
    put("requestedOn", requestedOn)
})

fun Row.toChargeResponseRow(): ChargeResponseRow = ChargeResponseRow(
    key = key,
    attempt = fields["attempt"] as Ref.Persisted,
    outcome = Verdict.of(fields["outcome"] as String),
    respondedOn = fields["respondedOn"] as Instant,
)

fun ChargeResponseRow.toRow(): Row = Row("ChargeResponse", key, buildMap {
    put("attempt", attempt)
    put("outcome", outcome.word)
    put("respondedOn", respondedOn)
})

fun Row.toAttemptTimeoutRow(): AttemptTimeoutRow = AttemptTimeoutRow(
    key = key,
    attempt = fields["attempt"] as Ref.Persisted,
    noticedOn = fields["noticedOn"] as Instant,
)

fun AttemptTimeoutRow.toRow(): Row = Row("AttemptTimeout", key, buildMap {
    put("attempt", attempt)
    put("noticedOn", noticedOn)
})

fun Row.toStockReservationRow(): StockReservationRow = StockReservationRow(
    key = key,
    order = fields["order"] as Ref.Persisted,
    reservedOn = fields["reservedOn"] as Instant,
)

fun StockReservationRow.toRow(): Row = Row("StockReservation", key, buildMap {
    put("order", order)
    put("reservedOn", reservedOn)
})

fun Row.toReservationReleaseRow(): ReservationReleaseRow = ReservationReleaseRow(
    key = key,
    reservation = fields["reservation"] as Ref.Persisted,
    releasedOn = fields["releasedOn"] as Instant,
)

fun ReservationReleaseRow.toRow(): Row = Row("ReservationRelease", key, buildMap {
    put("reservation", reservation)
    put("releasedOn", releasedOn)
})

fun Row.toReceiptRow(): ReceiptRow = ReceiptRow(
    key = key,
    attempt = fields["attempt"] as Ref.Persisted,
    sentOn = fields["sentOn"] as Instant,
)

fun ReceiptRow.toRow(): Row = Row("Receipt", key, buildMap {
    put("attempt", attempt)
    put("sentOn", sentOn)
})

fun Row.toShipmentRow(): ShipmentRow = ShipmentRow(
    key = key,
    order = fields["order"] as Ref.Persisted,
    shippedOn = fields["shippedOn"] as Instant,
)

fun ShipmentRow.toRow(): Row = Row("Shipment", key, buildMap {
    put("order", order)
